def find_first_negative(lst):
    i = 0
    while i < len(lst):
        if lst[i] < 0:
            return lst[i]
        i += 1
    return None

def index_of_max(lst):
    if not lst:
        return 0
    best = 0
    i = 1
    while i < len(lst):
        if lst[i] > lst[best]:
            best = i
        i += 1
    return best

def word_index_map(words):
    out = {}
    i = 0
    while i < len(words):
        if words[i] not in out:
            out[words[i]] = i
        i += 1
    return out

def fib_iter(n):
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def join_words(words, sep):
    if not words:
        return ''
    out = words[0]
    i = 1
    while i < len(words):
        out += sep + words[i]
        i += 1
    return out

def count_above(lst, t):
    c = 0
    i = 0
    while i < len(lst):
        if lst[i] > t:
            c += 1
        i += 1
    return c

def max_list(lst):
    if not lst:
        return None
    best = lst[0]
    i = 1
    while i < len(lst):
        if lst[i] > best:
            best = lst[i]
        i += 1
    return best

def factorial_rec(n):
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

